def gen(rng):
    def build(n, chain, vmax):
        val = [rng.randint(-vmax, vmax) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            if i <= chain:
                k = len(slots) - 1 - rng.randint(0, 1)
            else:
                k = rng.randrange(len(slots))
            slots[k], slots[-1] = slots[-1], slots[k]
            p, side = slots.pop()
            if side == 0:
                L[p] = i
            else:
                R[p] = i
            slots.append((i, 0))
            slots.append((i, 1))
        return val, L, R

    def ser(val, L, R):
        out = [str(val[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (L[u], R[u]):
                if c < 0:
                    out.append('null')
                else:
                    out.append(str(val[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    tests = ['7', '1 null 2 null 3', '1 2 null 3 null 4', '5 3 8 1 4 null 9 null null 7', '1 2 3', '1 null 2', '1 2', '4 2 6 1 3 5 7']
    for _ in range(12):
        n = rng.randint(1, 25)
        tests.append(ser(*build(n, rng.choice([0, 0, n // 2, n]), rng.choice([3, 10000]))))
    tests.append(ser(*build(5000, 4990, 10000)))
    tests.append(ser(*build(100000, 0, 10000)))
    tests.append(ser(*build(100000, 4900, 10000)))
    tests.append(ser(*build(60000, 4900, 10000)))
